'use strict';
/* Existing stream, evidence, plan and playback components. */
function allEvents(r){return r.steps.flatMap((step,index)=>step.events.map(e=>({...e,step:e.step??index}))).sort((a,b)=>a.at-b.at);}

function actualFrames(r){return allEvents(r).filter(e=>e.frame&&['validation','observation'].includes(e.type));}

function frameLabel(kind){return kind==='home'?'首页':kind?.startsWith('password')?'密码页':'邮箱页';}

function latestFrame(r){return actualFrames(r).at(-1)||null;}

function imageButton(r,kind,at,label,eventId,role='result',large=false){if(!kind)return '';return `<button class="evidence-image ${large?'large':''}" data-action="open-image" data-kind="${esc(kind)}" data-at="${at}" data-id="${esc(eventId||'')}" data-role="${role}" aria-label="打开${label}">${phoneSVG(kind,r.config.account,false,false,at)}<span class="image-caption"><strong>${label}</strong><span>${clock(at)} · ${frameLabel(kind)}</span></span>${icon('expand')}</button>`;}

function readableText(text){if(text.length<320)return `<p class="message-text">${esc(text)}</p>`;return `<details class="long-output"><summary><span>${esc(text.slice(0,260))}…</span><span class="text-link">展开全文</span></summary><p class="message-text">${esc(text)}</p></details>`;}

function rawRecord(e){return `<details class="raw-record" data-preserve="raw-${esc(e.id)}"><summary>${icon('code')}工具参数与原始记录</summary><pre>${esc(typeof e.tool==='string'?e.tool:JSON.stringify(e.tool||{},null,2))}</pre><dl><dt>事件</dt><dd>${esc(e.id)}</dd>${e.actionId?`<dt>关联动作</dt><dd>${esc(e.actionId)}</dd>`:''}${e.callId?`<dt>调用</dt><dd>${esc(e.callId)}</dd>`:''}</dl></details>`;}

function messageShell(id,role,title,at,body,extra=''){return `<article class="message ${role} ${extra}" id="msg-${esc(id)}" data-message-id="${esc(id)}"><div class="message-avatar">${role==='user'?'我':role==='result'?icon('check'):'A'}</div><div class="message-body"><div class="message-byline"><strong>${title}</strong><time>${clock(at)}</time></div>${body}</div></article>`;}

function messagesForRun(r){const s=viewState(),events=allEvents(r),last=events.at(-1),intent=r.intent||{id:r.id+'-goal',at:r.started,text:r.snapshot.objective};let html=messageShell(intent.id,'user','我',intent.at,readableText(intent.text));html+=`<div class="device-used">${icon('device')}<span>已使用 <strong>${esc(r.config.device)}</strong></span><time>${clock(r.started)}</time></div>`;
 const instructions=r.instructions.map(i=>({id:i.id+'-user',at:i.at,type:'user-instruction',instruction:i})),adjustments=(r.adjustments||[]).map((a,i)=>({id:r.id+'-plan-'+i,at:a.at,type:'plan-update',text:a.text,step:a.step}));
 const combined=[...events.filter(e=>e.type!=='model'),...instructions,...adjustments].sort((a,b)=>a.at-b.at);
 for(const e of combined){const selected=s.selected===e.id,current=e.id===last?.id,step=r.steps[e.step];
  if(e.type==='user-instruction'){html+=messageShell(e.id,'user','我 · 补充指令',e.at,readableText(e.instruction.text)+`<span class="instruction-state">${e.instruction.state==='pending'?(ongoing(r)?'待记录':'运行结束，采纳未确认'):'已记录 · 采纳未确认'}</span>`);continue;}
  if(e.type==='plan-update'){html+=`<div class="stream-event" id="msg-${e.id}">${icon('file')}<div><strong>计划调整</strong><p>${esc(e.text)}</p><button class="text-link" data-action="show-plan">查看计划更新</button></div><time>${clock(e.at)}</time></div>`;continue;}
  if(e.type==='output'||e.type==='model-output'){html+=messageShell(e.id,'agent',e.source==='legacy-example'?'原项目示例输出':'模型输出',e.at,readableText(e.text)+`<div class="decision-context"><span class="evidence-label">决策截图 · 本次调用实际输入</span>${e.decisionFrame?imageButton(r,e.decisionFrame,e.at,'决策截图',e.id,'decision',selected||current):'<span class="missing-evidence">未记录输入截图，无法确认本次模型实际看到了哪一帧。</span>'}</div>`+rawRecord(e),selected?'selected':'');continue;}
  if(['action','retry'].includes(e.type)){const verification=events.find(v=>v.actionId===e.id);html+=messageShell(e.id,'agent','Artemis',e.at,`<div class="action-card ${selected?'selected':''}"><button class="action-card-head" data-action="select-message" data-id="${e.id}"><span class="od-field"><span class="action-type">${e.type==='retry'?'ACTION · RETRY':'ACTION'}</span><strong>${esc(e.type==='retry'?'重试点击下一步':step?.name||'执行动作')}</strong></span>${badge('sent','step')}</button><p class="action-copy">${esc(e.text)}</p><div class="action-id mono">${e.id}</div>${rawRecord(e)}${verification?`<div class="action-result">${badge(verification.status||'insufficient','step')}<span>${esc(verification.text)}</span></div>`:'<div class="action-result muted">尚无与本动作明确关联的校验结果。</div>'}</div>`);continue;}
  if(e.type==='validation'||e.type==='observation'){const issue=['failed','insufficient'].includes(e.status),full=selected||current||issue;html+=messageShell(e.id,'agent',e.status==='recovered'?'恢复校验':'结果校验',e.at,`<div class="validation ${issue?'issue':''}"><div class="od-row">${badge(e.status||'insufficient','step')}<button class="text-link" data-action="select-message" data-id="${e.id}">${selected?'当前记录':'查看此记录'}</button></div>${readableText(e.text)}${e.status==='failed'?`<div class="expectation"><span>预期</span><p>${esc(step.expected)}</p></div>`:''}${e.frame?`<div class="evidence-label">动作结果截图 <span class="mono">${e.actionId?esc(e.actionId):'原记录未提供 actionId'}</span></div>${imageButton(r,e.frame,e.at,'动作结果',e.id,'result',full)}`:'<div class="missing-evidence">未记录动作结果截图，不以其他帧替代。</div>'}${rawRecord(e)}</div>`,selected?'selected':'');continue;}
  html+=`<div class="stream-event" id="msg-${e.id}">${icon(e.type==='control'?'stop':'info')}<div><strong>${e.type==='instruction'?'指令状态':e.type==='control'?'运行控制':'执行事件'}</strong><p>${esc(e.text)}</p>${e.tool?rawRecord(e):''}</div><time>${clock(e.at)}</time></div>`;
 }
 if(!combined.some(e=>e.type==='output'||e.type==='model-output'))html+=`<div class="source-note">${icon('info')}<span>这份记录未保存原始模型输出与输入截图，当前只显示已有动作和校验事件。</span></div>`;
 if(r.custom&&ongoing(r))html+=`<div class="stream-event">${icon('clock')}<div><strong>等待执行接入</strong><p>目标与设备已记录；当前没有该场景的真实执行输出。</p></div></div>`;
 if(!ongoing(r))html+=resultMessage(r);return html;
}

function resultMessage(r){const passed=r.status==='passed',incomplete=r.steps.filter(x=>!['verified','recovered'].includes(x.status));return messageShell(r.id+'-result','result','执行结论',r.ended||r.started,`<div class="result-message"><div class="od-row">${badge(r.status)}<h3>${passed?'测试目标已完成':r.status==='stopped'?'本次执行已停止':'测试目标未完成'}</h3></div><p>${passed?'登录与首页均已验证。首次点击下一步的异常已在重试后恢复。':incomplete.length?'尚未完成：'+incomplete.map(x=>x.name).join('、')+'。':'已有验证结果已保留。'}</p>${r.steps.some(x=>x.recovery)?'<p class="muted">首次失败和恢复证据均保留；恢复不等同于整次运行通过。</p>':''}<div class="od-cluster">${btn('回放本次执行','open-replay','small','play')}${r.steps.some(x=>x.issue)?btn('查看异常证据','result-evidence','text','file'):''}<button class="btn text" data-action="run-facts">本次运行信息</button></div></div>`);}

function renderMessages(){const c=getCase(),r=currentRun(),s=viewState(),scroll=$('#message-scroll'),existing=scroll?.scrollTop||0,root=$('#message-list');if(!root)return;const expanded=[...root.querySelectorAll('details[open][data-preserve]')].map(el=>el.dataset.preserve);root.innerHTML=r?messagesForRun(r):c?.pending?messageShell(c.pending.id,'user','我',c.pending.at,readableText(c.pending.text))+deviceCard(c):emptyMessages(c);expanded.forEach(id=>root.querySelector(`[data-preserve="${CSS.escape(id)}"]`)?.setAttribute('open',''));if(scroll)scroll.scrollTop=existing;updateNewEvents();}

function updateNewEvents(){const s=viewState(),bar=$('#new-events-bar');if(!bar)return;bar.hidden=!s.unread;bar.innerHTML=`<button data-action="follow-messages">${s.unread} 条新消息 · 回到最新 ${icon('down')}</button>`;}


function renderRight(){const s=viewState(),root=$('#device-content');if(!root)return;const expanded=[...root.querySelectorAll('details[open][data-plan-key]')].map(x=>x.dataset.planKey);const scroll=$('.plan-scroll',root)?.scrollTop||0;$$('[data-action="right-tab"]').forEach(b=>{b.classList.toggle('active',b.dataset.value===s.rightTab);b.setAttribute('aria-selected',b.dataset.value===s.rightTab);});$('[data-action="pin-plan"]')?.setAttribute('aria-pressed',s.pinned);root.classList.toggle('plan-pinned',s.pinned&&s.rightTab==='live');root.innerHTML=s.rightTab==='plan'?renderPlan():s.rightTab==='replay'?renderReplay():renderLive()+(s.pinned?`<aside class="pinned-plan">${renderPlan(true)}</aside>`:'');expanded.forEach(key=>root.querySelector(`[data-plan-key="${CSS.escape(key)}"]`)?.setAttribute('open',''));const plan=$('.plan-scroll',root);if(plan)plan.scrollTop=scroll;}

function renderLive(){const c=getCase(),r=currentRun(),s=viewState();if(!r)return `<div class="live-view"><div class="viewer-meta"><span class="od-row">${icon('device')}等待连接设备</span><span class="connection-badge">未连接</span></div><div class="device-waiting"><div class="device-outline">${icon('device')}</div><h2>${c?.pending?'选择设备后开始':'设备画面将在这里显示'}</h2><p>${c?.pending?'左侧目标已提交，等待选择执行设备。':'提交测试目标，然后在消息中选择设备。'}</p></div><div class="viewer-footer"><span>直播连接与任务状态分别记录</span></div></div>`;
 const last=latestFrame(r),frame=!s.connected&&ongoing(r)?s.lastFrame:last?.frame,at=!s.connected&&ongoing(r)?s.lastAt:last?.at;
 return `<div class="live-view"><div class="viewer-meta"><span class="od-row">${icon('device')}${esc(r.config.device)}</span><span class="connection-badge ${ongoing(r)?s.connected?'green':'amber':''}">${!ongoing(r)?'执行已结束':s.connected?'直播已连接 · 模拟':'直播连接中断'}</span></div>${!ongoing(r)?`<div class="live-state ended"><div><strong>本次执行已结束</strong><span>${dateTime(r.ended)} · 保留最后可用画面</span></div>${btn('查看回放','open-replay','small','play')}</div>`:!s.connected?`<div class="live-state disconnected"><div><strong>直播连接中断</strong><span>最后画面 ${at?clock(at):'尚未收到'} · 任务${r.status==='running'?'仍在执行':'等待操作'}</span></div>${btn('重新连接','reconnect','small','refresh',offline?'disabled':'')}</div>`:''}<div class="live-canvas">${frame?`<button class="live-shot" data-action="open-image" data-kind="${frame}" data-at="${at}" data-id="${last?.id||''}" data-role="result" aria-label="放大当前设备画面">${phoneSVG(frame,r.config.account,false,false,at)}</button>`:`<div class="device-waiting"><div class="device-outline">${icon('device')}</div><h2>等待首帧画面</h2><p>${r.custom?'尚未接入该场景的设备执行。':'已创建运行，等待页面观察结果。'}</p></div>`}</div><div class="viewer-footer"><span>${at?'最后画面 '+clock(at):'尚无画面'} · 示例重建</span><span class="od-row">任务 ${badge(r.status)}</span></div></div>`;
}

function planData(r){if(!r)return null;const versions=r.planVersions||[];const selected=viewState().selectedVersion;if(selected==='latest'&&r.taskPlan)return r.taskPlan;const version=selected==='latest'?versions.at(-1):versions.find((v,i)=>String(v.id??i)===selected);if(version)return version.content??version.plan??version.raw??version;return r.taskPlan??r.task_plan??r.rawTaskPlan??null;}

function planValue(value,key='root',depth=0){if(value===null)return '<span class="muted">null</span>';if(typeof value!=='object')return `<div class="plan-text">${esc(String(value))}</div>`;if(Array.isArray(value))return `<div class="plan-children">${value.map((v,i)=>planValue(v,key+'-'+i,depth+1)).join('')}</div>`;const title=value.title??value.name??value.label??value.id??'任务内容',status=value.status;const kind=value.type??value.kind;const fields=Object.entries(value).filter(([k])=>!['title','name','label'].includes(k)||k!==(value.title!==undefined?'title':value.name!==undefined?'name':'label'));return `<details class="plan-node" data-plan-key="${esc(key)}" ${depth<3?'open':''}><summary><span class="od-field"><strong>${esc(String(title))}</strong>${kind?`<small>${esc(String(kind))}</small>`:''}</span>${status?`<span class="badge ${['completed','done','passed','verified'].includes(status)?'green':['running','active','in_progress'].includes(status)?'blue':''}">${esc(String(status))}</span>`:''}</summary><div class="plan-node-content">${fields.map(([k,v])=>`<div class="plan-property"><span class="plan-key">${esc(k)}</span>${k==='eventIds'&&Array.isArray(v)?v.map(id=>`<button class="text-link" data-action="plan-event" data-id="${esc(id)}">?????? ? ${esc(id)}</button>`).join(''):planValue(v,key+'-'+k,depth+1)}</div>`).join('')}</div></details>`;}

function renderPlan(pinned=false){const r=currentRun(),raw=planData(r),versions=r?.planVersions||[];return `<div class="plan-panel"><header class="plan-panel-head"><div><h2>TaskPlan</h2><p>计划目标、组织方式与检查条件</p></div>${pinned?ibtn('close','pin-plan','收起并排计划'):''}</header>${versions.length?`<label class="plan-version-label">计划版本<select id="plan-version"><option value="latest">最新版本</option>${versions.map((v,i)=>`<option value="${esc(v.id??i)}" ${viewState().selectedVersion===String(v.id??i)?'selected':''}>${esc(v.title||'版本 '+(i+1))}${v.at?' · '+clock(v.at):''}</option>`).join('')}</select></label>`:''}<div class="plan-scroll">${!r?'<div class="plan-empty"><h3>尚未收到执行计划</h3><p>选择设备并开始后，计划会在这里显示。</p></div>':raw?`<div class="plan-source">按记录中的原始字段与层级展示</div>${planValue(raw)}<details class="raw-record"><summary>查看完整原文</summary><pre>${esc(typeof raw==='string'?raw:JSON.stringify(raw,null,2))}</pre></details>`:`<div class="plan-source missing"><strong>仅有阶段摘要</strong><p>此运行未保存完整原始 TaskPlan。以下保留已有目标与状态，不补写层级、循环或断言结构。</p></div><div class="legacy-plan">${r.steps.map((step,i)=>`<div class="legacy-task"><div class="od-row"><span class="task-index">${i+1}</span><strong>${step.name}</strong>${badge(step.status,'step')}</div><p><span>已有预期：</span>${esc(step.expected)}</p></div>`).join('')}</div>`}${r&&(r.adjustments||[]).length?`<section class="plan-updates"><h3>已记录的计划调整</h3>${r.adjustments.map(a=>`<div class="plan-update"><time>${clock(a.at)}</time><p>${esc(a.text)}</p></div>`).join('')}</section>`:''}<p class="plan-footnote">计划状态不等于测试通过率；测试结论见消息流末尾。</p></div></div>`;}

function renderReplay(){const r=currentRun(),s=viewState();if(!r)return '<div class="device-waiting"><h2>还没有可回放记录</h2><p>执行产生画面后，可在这里按事件回看。</p></div>';const frames=actualFrames(r);s.replay=Math.max(0,Math.min(s.replay,frames.length-1));const e=frames[s.replay];return `<div class="replay-view"><div class="viewer-meta"><span class="od-row">${icon('play')}${r.id} · 事件回放</span><span>${e?clock(e.at):'暂无画面'}</span></div><div class="replay-event">${e?`<span class="mono">${e.id}</span><p>${esc(e.text)}</p><span class="badge">动作结果截图</span>`:'尚未收到可用截图'}</div><div class="live-canvas">${e?`<button class="live-shot" data-action="open-image" data-kind="${e.frame}" data-at="${e.at}" data-id="${e.id}" data-role="result" aria-label="打开回放画面">${phoneSVG(e.frame,r.config.account,false,false,e.at)}</button>`:`<div class="device-waiting">${icon('file')}<p>没有关联画面，无法回放。</p></div>`}</div><div class="replay-controls">${ibtn(s.playing?'pause':'play','play-replay',s.playing?'暂停回放':'播放事件回放',!frames.length?'disabled':'')}<div class="od-field od-fill"><label class="sr-only" for="replay-position">回放位置</label><input id="replay-position" type="range" min="0" max="${Math.max(0,frames.length-1)}" value="${s.replay}" ${!frames.length?'disabled':''}><div class="replay-labels"><span>${e?duration((e.at-r.started)/1000):'00:00'}</span><span>${frames.length?duration((frames.at(-1).at-r.started)/1000):'00:00'}</span></div></div>${e?ibtn('arrow','replay-message','定位关联消息',`data-id="${e.id}"`):''}</div><div class="viewer-footer"><span>按记录切换画面 · 非真实录屏</span>${btn(ongoing(r)?'回到实时':'返回直播位置','back-live','text')}</div></div>`;}

function stopReplay(){clearInterval(playTimer);playTimer=null;for(const v of workspaceStates.values())v.playing=false;}

function toggleReplay(){const r=currentRun(),s=viewState();if(!r)return;if(s.playing){stopReplay();renderRight();return;}const frames=actualFrames(r);if(!frames.length)return;if(s.replay>=frames.length-1)s.replay=0;s.playing=true;renderRight();playTimer=setInterval(()=>{if(currentRun()?.id!==r.id){stopReplay();return;}if(s.replay>=actualFrames(r).length-1){stopReplay();renderRight();return;}s.replay++;renderRight();},1500);}

function bindWorkspace(){const scroll=$('#message-scroll');scroll.addEventListener('scroll',()=>{const s=viewState();s.scroll=scroll.scrollTop;s.following=scroll.scrollHeight-scroll.clientHeight-scroll.scrollTop<72;},{passive:true});const handle=$('#split-handle'),grid=$('#workspace-grid');function setRatio(percent){const value=Math.max(35,Math.min(65,percent));grid.style.setProperty('--left-share',value+'%');handle.setAttribute('aria-valuenow',String(Math.round(value)));try{sessionStorage.setItem('artemis-split',String(value));}catch{}}try{const value=sessionStorage.getItem('artemis-split');if(value)setRatio(Number(value));}catch{}handle.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();setRatio(Number(handle.getAttribute('aria-valuenow'))+(e.key==='ArrowRight'?2:-2));});handle.addEventListener('pointerdown',e=>{handle.setPointerCapture(e.pointerId);const box=grid.getBoundingClientRect();const move=ev=>setRatio((ev.clientX-box.left)/box.width*100);const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end);});}

function followMessages(){const s=viewState();s.following=true;s.unread=0;renderMessages();const scroll=$('#message-scroll');scroll.scrollTop=scroll.scrollHeight;s.scroll=scroll.scrollTop;}

function locateMessage(id){const s=viewState();s.selected=id;s.following=false;renderMessages();const el=document.getElementById('msg-'+id);if(el){const scroll=$('#message-scroll');scroll.scrollTop+=el.getBoundingClientRect().top-scroll.getBoundingClientRect().top-20;s.scroll=scroll.scrollTop;el.classList.add('selected');}}


function dialog(title,body,actions='',subtitle='',cls=''){const el=$('#modal');if(!el.open)dialogReturn=document.activeElement;el.className=cls;el.innerHTML=`<header class="dialog-head"><div><h2 id="dialog-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${ibtn('close','close-dialog','关闭')}</header><div class="dialog-body">${body}</div><footer class="dialog-actions">${actions||btn('关闭','close-dialog')}</footer>`;if(!el.open)el.showModal();}

function closeDialog(){const el=$('#modal');if(el?.open)el.close();unsavedEdit=false;modalKind='';modalContext={};if(dialogReturn?.isConnected)dialogReturn.focus();}

function confirmDialog(title,text,label,callback){modalKind='confirm';modalContext={callback};dialog(title,`<p>${esc(text)}</p>`,btn('取消','close-dialog')+btn(label,'confirm','primary'));}

function field(id,label,control,hint=''){return `<div class="field"><label for="${id}">${label}</label>${control}${hint?`<p class="hint">${hint}</p>`:''}<p class="field-error" id="${id}-error" hidden></p></div>`;}

function inferName(text){const first=text.split(/[。！？\n]/)[0].trim();return first.length>28?first.slice(0,28):first||'未命名 Case';}

function showRunFacts(r){modalKind='facts';dialog('本次运行信息',`<dl class="facts"><dt>Case</dt><dd>${esc(r.snapshot.name)} · ${r.caseId}</dd><dt>运行</dt><dd>${r.id} · ${runStates[r.status][0]}</dd><dt>开始</dt><dd>${dateTime(r.started)}</dd><dt>结束</dt><dd>${r.ended?dateTime(r.ended):'尚未结束'}</dd><dt>定义版本</dt><dd>v${r.snapshot.revision}</dd><dt>应用</dt><dd>${esc(r.config.appName||'未记录')}</dd><dt>环境</dt><dd>${esc(r.config.environment||'未记录')}</dd><dt>设备</dt><dd>${esc(r.config.device)}</dd><dt>执行工具</dt><dd>${esc(r.config.tool)}</dd></dl><p class="small muted" style="margin-top:16px">这是本次启动时的记录；编辑 Case 不会改变历史快照。</p>`);}

function showImage(kind,at,id,role){const r=currentRun();if(!r)return;modalKind='image';modalContext={kind,at,id,role,zoom:1};renderImageDialog();}

function renderImageDialog(){const r=currentRun(),d=modalContext;dialog(d.role==='decision'?'决策截图':'动作结果截图',`<div class="image-dialog-frame">${phoneSVG(d.kind,r.config.account,false,false,d.at)}</div><p class="small muted">${esc(d.id)} · ${clock(d.at)} · 示例重建</p>`,`<span class="small muted" style="margin-right:auto">${Math.round(d.zoom*100)}%</span>${ibtn('back','zoom-out','缩小')}${ibtn('plus','zoom-in','放大')}${btn('关闭','close-dialog')}`,'仅查看所选图片，右侧直播保持原状态','image-dialog');$('.image-dialog-frame svg').style.width=(300*d.zoom)+'px';}


function validationError(el,text){el.setAttribute('aria-invalid',text?'true':'false');const error=$('#'+el.id+'-error');if(error){error.hidden=!text;error.textContent=text;}}